package dev.ravichimkar.portfolio.security;
import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{Claims c=jwt.parse(h.substring(7)); List<?> rs=c.get("roles",List.class); var a=rs==null?List.<SimpleGrantedAuthority>of():rs.stream().map(x->new SimpleGrantedAuthority("ROLE_"+x)).toList(); org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(c.getSubject(),null,a));}catch(Exception ignored){org.springframework.security.core.context.SecurityContextHolder.clearContext();} chain.doFilter(req,res);} }
